func modInverse(a, m int) int {
	g, x, _ := extendedGCD(a, m)
	if g != 1 {
		return -1
	}
	return (x % m + m) % m
}

func extendedGCD(a, b int) (int, int, int) {
	if a == 0 {
		return b, 0, 1
	}
	g, x, y := extendedGCD(b%a, a)
	return g, y - (b/a)*x, x
}

func crt(r1, m1, r2, m2 int) (int, bool) {
	g, p, q := extendedGCD(m1, m2)
	if (r2-r1)%g != 0 {
		return 0, false
	}
	lcm := m1 / g * m2
	res := (r1 + (r2-r1)/g*p%m2*m1) % lcm
	if res < 0 {
		res += lcm
	}
	return res, true
}
