	// k*(p-1) ≡ c - r mod p
	// k ≡ (c - r) * inv(p-1) mod p
	// k = ((c - r) * inv_p_minus_1) mod p
	// n = r + k*(p-1)
	// n mod (p*(p-1)) = r + (((c - r) * inv_p_minus_1) mod p) * (p-1)

	// The period is p*(p-1)
	period := p * (p - 1)

	count := int64(0)

	for r := int64(0); r < p-1; r++ {
