			k += p
		}
		n0 := r + k*(p-1)
		// n0 is the smallest non-negative solution
		// n ≡ n0 mod period

		// Count n in [1, x] with n ≡ n0 mod period
		if n0 == 0 {
			// n0 = 0 means n ≡ 0 mod period, so n = period, 2*period, ...
			// But we need n >= 1, so the first valid n is period
			if period <= x {
				count += (x - period) / period + 1
			}
		} else {
			// n0 >= 1 (since r >= 0 and k >= 0, and if r=0 then k could be 0)
			// Actually n0 could be 0 if r=0 and k=0
			// But we handled that case above
			// For n0 >= 1:
			if n0 <= x {
				count += (x - n0) / period + 1
			}
		}
	}

