package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	var a, b, p, x int64
	fmt.Fscan(reader, &a, &b, &p, &x)

	// Find the period of a^n mod p
	// Since p is prime, the multiplicative order of a divides p-1
	// We'll compute the period by finding the smallest k such that a^k ≡ 1 mod p
	period := findPeriod(a, p)

	// For each residue r of n mod period, find the corresponding value of a^n mod p
	// Then solve for n in the congruence n * a^n ≡ b mod p
	// This becomes n * c ≡ b mod p, where c = a^r mod p
	// The solution is n ≡ b * c^{-1} mod p (if c != 0)

	// Precompute a^r mod p for r from 0 to period-1
	powers := make([]int64, period)
	powers[0] = 1
	for i := int64(1); i < period; i++ {
		powers[i] = (powers[i-1] * a) % p
	}

	count := int64(0)
	for r := int64(0); r < period; r++ {
		c := powers[r]
		if c == 0 {
			continue
		}
		// Solve n * c ≡ b mod p
		// n ≡ b * c^{-1} mod p
		cInv := modInverse(c, p)
		n0 := (b * cInv) % p
		if n0 < 0 {
			n0 += p
		}
		// n ≡ n0 mod p, and n ≡ r mod period
		// Use CRT to find n mod (p * period)
		// n = n0 + p * k, and n ≡ r mod period
		// n0 + p*k ≡ r mod period
		// p*k ≡ (r - n0) mod period
		// k ≡ (r - n0) * p^{-1} mod period
		diff := (r - n0) % period
		if diff < 0 {
			diff += period
		}
		pInv := modInverse(p, period)
		k0 := (diff * pInv) % period
		if k0 < 0 {
			k0 += period
		}
		nStart := n0 + p*k0
		// nStart is the smallest positive solution
		// All solutions are nStart + m * (p * period) for m >= 0
		modulus := p * period
		if nStart > x {
			continue
		}
		count += (x - nStart) / modulus + 1
	}

	fmt.Println(count)
}

func findPeriod(a, p int64) int64 {
	// Find the smallest k such that a^k ≡ 1 mod p
	// This is the multiplicative order of a modulo p
	// Since p is prime, the order divides p-1
	// We'll factor p-1 and check divisors
	phi := p - 1
	order := phi
	// Factor phi
	factors := factorize(phi)
	// For each prime factor, try to reduce the order
	for _, f := range factors {
		for order%f == 0 {
			// Check if a^(order/f) ≡ 1 mod p
			if powMod(a, order/f, p) == 1 {
				order /= f
			} else {
				break
			}
		}
	}
	return order
}

func factorize(n int64) []int64 {
	factors := []int64{}
	d := int64(2)
	for d*d <= n {
		for n%d == 0 {
			factors = append(factors, d)
			n /= d
		}
		d++
	}
	if n > 1 {
		factors = append(factors, n)
	}
	// Remove duplicates
	seen := map[int64]bool{}
	unique := []int64{}
	for _, f := range factors {
		if !seen[f] {
			seen[f] = true
			unique = append(unique, f)
		}
	}
	return unique
}

func powMod(base, exp, mod int64) int64 {
	result := int64(1)
	base %= mod
	for exp > 0 {
		if exp&1 == 1 {
			result = (result * base) % mod
		}
		base = (base * base) % mod
		exp >>= 1
	}
	return result
}

func modInverse(a, m int64) int64 {
	// Extended Euclidean Algorithm
	g, x, _ := extendedGCD(a, m)
	if g != 1 {
		return -1 // No inverse exists
	}
	x = (x % m + m) % m
	return x
}

func extendedGCD(a, b int64) (int64, int64, int64) {
	if a == 0 {
		return b, 0, 1
	}
	g, x, y := extendedGCD(b%a, a)
	return g, y - (b/a)*x, x
}
