	for r := 0; r < p-1; r++ {
		// Compute a^r mod p
		ar := powMod(a, r, p)
		// Compute the modular inverse of ar mod p
		inv := modInverse(ar, p)
		// Compute n0 = b * inv mod p
		n0 := (b * inv) % p
		if n0 == 0 {
			n0 = p
		}
		// Check if n0 is within the range [1, x]
		if n0 > x {
			continue
		}
		// Check if n0 ≡ r mod (p-1)
		if (n0-r)%(p-1) != 0 {
			continue
		}
		// Calculate the number of valid n in this residue class
		// n = n0 + k*(p-1) <= x
		// k >= 0
		// k <= (x - n0)/(p-1)
		kMax := (x - n0) / (p - 1)
		if kMax >= 0 {
			count += int(kMax + 1)
		}
	}

	fmt.Println(count)
}

func powMod(a, b, mod int) int {
	res := 1
	a = a % mod
	for b > 0 {
		if b%2 == 1 {
			res = (res * a) % mod
		}
		a = (a * a) % mod
		b = b / 2
	}
	return res
}

func modInverse(a, mod int) int {
	return powMod(a, mod-2, mod)
}

func bufreader() *bufio.Reader {
	return bufio.NewReader(os.Stdin)
}

func readInt(reader *bufio.Reader) int {
	var n int = 0
	var ch byte
	var err error
	for {
		ch, err = reader.ReadByte()
		if err != nil {
			break
		}
		if ch == ' ' || ch == '\n' {
			if n != 0 {
				break
			}
			continue
		}
		n = n*10 + int(ch-'0')
	}
	return n
}
