		// Number of valid k values
		// k = k_mod_p, k_mod_p + p, k_mod_p + 2p, ...
		// We need k <= max_k
		if k_mod_p > max_k {
			continue
		}

		// Count how many k values satisfy k ≡ k_mod_p mod p and 0 <= k <= max_k
		count += (max_k - k_mod_p) / p + 1
	}

	fmt.Println(count)
}

// Extended Euclidean Algorithm to find modular inverse
func modInverse(a, m int64) int64 {
	g, x := extendedGCD(a, m)
	if g != 1 {
