		return 0
	}
	x = (x % m + m) % m
	return x
}

func extendedGCD(a, b int64) (int64, int64) {
	if b == 0 {
		return a, 1
	}
	g, x := extendedGCD(b, a%b)
	return g, x - (a/b)*x
