}

// powMod computes (base^exp) % mod
func powMod(base, exp, mod int64) int64 {
	result := int64(1)
	base = base % mod
	for exp > 0 {
		if exp%2 == 1 {
			result = (result * base) % mod
		}
		exp = exp >> 1
		base = (base * base) % mod
	}
	return result
}

// modInverse computes the modular inverse of a modulo m using Fermat's little theorem
func modInverse(a, m int64) int64 {
	return powMod(a, m-2, m)
}

// crt solves the system of congruences:
// x ≡ a1 (mod m1)
// x ≡ a2 (mod m2)
// Returns the smallest non-negative solution, or -1 if no solution exists
func crt(a1, m1, a2, m2 int64) int64 {
	// Ensure m1 and m2 are positive
	if m1 < 0 {
		m1 = -m1
	}
	if m2 < 0 {
		m2 = -m2
	}
	// Compute the GCD and LCM of m1 and m2
	gcd, lcm := extendedGCD(m1, m2)
	if (a2-a1)%gcd != 0 {
		return -1
	}
	// Compute the solution
	mod := lcm
	// Compute the coefficient for the first congruence
	coeff := (a2 - a1) / gcd
	// Compute the inverse of (m1/gcd) modulo (m2/gcd)
	inv, _ := modInverseExtended(m1/gcd, m2/gcd)
	// Compute the solution
	x := (a1 + (coeff * (m1 % mod) * inv) % mod) % mod
	if x < 0 {
		x += mod
	}
	return x
}

// extendedGCD computes the GCD of a and b, and the coefficients x and y such that a*x + b*y = gcd(a, b)
func extendedGCD(a, b int64) (gcd, x, y int64) {
	if b == 0 {
		return a, 1, 0
	}
	gcd, x1, y1 := extendedGCD(b, a%b)
	x = y1
	y = x1 - (a/b)*y1
	return gcd, x, y
}

// modInverseExtended computes the modular inverse of a modulo m using the extended Euclidean algorithm
func modInverseExtended(a, m int64) (int64, int64) {
	gcd, x, _ := extendedGCD(a, m)
	if gcd != 1 {
		return 0, 0 // inverse doesn't exist
	}
	return (x % m + m) % m, 1
}
