package main

import "fmt"

func main() {
	var a, b, p, x int
	fmt.Scan(&a, &b, &p, &x)

	count := 0
	period := p * (p - 1) // Period of a^n mod p is p-1, and n mod p has period p

	// Iterate over all possible residues of n mod period
	for r := 0; r < period; r++ {
		// Compute a^r mod p
		ar := powMod(a, r, p)
		// Compute r * ar mod p
		val := (r * ar) % p
		if val == b {
			// Count how many n <= x with n ≡ r (mod period)
			if r == 0 {
				// n = k * period, k >= 1
				count += int(x / period)
			} else {
				// n = k * period + r, k >= 0
				if r <= x {
					count += int((x - r) / period) + 1
				}
			}
		}
	}

	fmt.Println(count)
}

func powMod(a, n, mod int) int {
	result := 1
	base := a % mod
	for n > 0 {
		if n&1 == 1 {
			result = (result * base) % mod
		}
		base = (base * base) % mod
		n >>= 1
	}
	return result
}
