func main() {
	reader := bufio.NewReader(os.Stdin)
	var a, b, p, x int64
	fmt.Fscan(reader, &a, &b, &p, &x)

	// Precompute powers of a modulo p up to p-1
	powA := make([]int64, p)
	powA[0] = 1
	for i := int64(1); i < p; i++ {
		powA[i] = (powA[i-1] * a) % p
	}

	// Precompute inverses of a modulo p using Fermat's little theorem
	invA := make([]int64, p)
	invA[1] = modInverse(a, p)
	for i := int64(2); i < p; i++ {
		invA[i] = (invA[i-1] * invA[1]) % p
	}

	// Precompute inverses of integers 1..p-1 modulo p
	inv := make([]int64, p)
	inv[1] = 1
	for i := int64(2); i < p; i++ {
		inv[i] = (p - (p/i)*inv[p%i]%p) % p
	}

	count := int64(0)
	for k := int64(0); k < p-1; k++ {
		// Compute a^k mod p
		ak := powA[k]
		// Compute a^{-k} mod p
		inv_ak := invA[k]

		// Compute (b * inv_ak) mod p
		term := (b * inv_ak) % p

		// Compute n0 = term * inv[k] mod p
		n0 := (term * inv[k]) % p

		// Compute the minimal n for this k: n = n0 + k*p
		n_min := n0 + k*p

		if n_min > x {
			continue
		}

		// Compute the number of terms in the arithmetic sequence
		// n = n_min, n_min + p*(p-1), n_min + 2*p*(p-1), ...
		// The step is p*(p-1)
		step := p * (p - 1)
		// Number of terms: floor((x - n_min)/step) + 1
		count += (x - n_min) / step + 1
	}

	fmt.Println(count)
}

func modInverse(a, p int64) int64 {
	return powMod(a, p-2, p)
}

func powMod(a, n, mod int64) int64 {
	res := int64(1)
	a = a % mod
	for n > 0 {
		if n%2 == 1 {
			res = (res * a) % mod
		}
		a = (a * a) % mod
		n = n / 2
	}
	return res
}
