	log_table := make([]int64, p)
	for i := range log_table {
		log_table[i] = -1
	}
	for k := int64(0); k < p-1; k++ {
		y := a_powers[k]
		if log_table[y] == -1 {
			log_table[y] = k
		}
	}

	count := int64(0)
	for k := int64(0); k < p; k++ {
		// Compute c_k = b * a_inv^k mod p
		c_k := (b * a_inv_powers[k]) % p

