					count += (x - n_min)/p + 1
				}
			}
		} else {
			// Look up log_table for c_k
			if c_k < p && log_table[c_k] != -1 {
				m := log_table[c_k]
				// n = k + m*p
				n_min := k + m*p
				if n_min <= x {
					count += (x - n_min)/p + 1
				}
			}
		}
	}

	fmt.Println(count)
}

// modInv computes the modular inverse of a mod p using Fermat's little theorem
func modInv(a, p int64) int64 {
	return powMod(a, p-2, p)
}

// powMod computes (base^exp) mod mod using fast exponentiation
func powMod(base, exp, mod int64) int64 {
	result := int64(1)
	base = base % mod
	for exp > 0 {
		if exp%2 == 1 {
			result = (result * base) % mod
		}
		exp = exp >> 1
		base = (base * base) % mod
	}
	return result
}
