		// n ≡ b * invAr mod p
		n0 := (b * invAr) % p
		if n0 < 0 {
			n0 += p
		}
		// Now n ≡ n0 mod p, and n ≡ r mod (p-1)
		// Solve CRT: n ≡ n0 mod p, n ≡ r mod (p-1)
		// Since p and p-1 are coprime (p is prime), CRT applies
		nSol := crt(n0, p, r, p-1)
		if nSol == -1 {
			continue
		}
		// Find the smallest positive solution
		mod := p * (p - 1)
		if nSol == 0 {
			nSol = mod
		}
		// Count numbers n = nSol + k*mod <= x
		if nSol <= x {
			count += (x - nSol) / mod + 1
		}
	}
	fmt.Println(count)
}

// powMod computes (base^exp) % mod
func powMod(base, exp, mod int64) int64 {
	result := int64(1)
	base = base % mod
	for exp > 0 {
		if exp%2 == 1 {
			result = (result * base) % mod
		}
		exp = exp >> 1
		base = (base * base) % mod
	}
	return result
}

// modInverse computes the modular inverse of a mod p using Fermat's little theorem
// Returns -1 if inverse doesn't exist
func modInverse(a, p int64) int64 {
	if a == 0 {
		return -1
	}
	return powMod(a, p-2, p)
}

// crt solves the system:
// x ≡ a1 mod m1
// x ≡ a2 mod m2
// Returns the solution mod (m1*m2), or -1 if no solution
func crt(a1, m1, a2, m2 int64) int64 {
	// Extended Euclidean Algorithm to find gcd and coefficients
	g, x, y := extendedGCD(m1, m2)
	if (a2-a1)%g != 0 {
		return -1
	}
	lcm := m1 / g * m2
	result := (a1 + (x*(a2-a1)/g)%lcm*m1) % lcm
	if result < 0 {
		result += lcm
	}
	return result
}

// extendedGCD finds gcd(a, b) and x, y such that ax + by = gcd(a, b)
func extendedGCD(a, b int64) (int64, int64, int64) {
	if b == 0 {
		return a, 1, 0
	}
	g, x, y := extendedGCD(b, a%b)
	return g, y, x - (a/b)*y
}
