	// Since a^n mod p has period `period`, we can group n by their residue mod period
	// For each residue r in [0, period-1], we solve n ≡ r mod period and n * a^r ≡ b mod p

	count := int64(0)

	// For each possible residue r of n mod period
	for r := int64(0); r < period; r++ {
		// We need n ≡ r mod period and n * a^r ≡ b mod p
		// n = r + k * period for some k >= 0
		// So (r + k * period) * a^r ≡ b mod p
		// k * period * a^r ≡ b - r * a^r mod p
		// k ≡ (b - r * a^r) * (period * a^r)^(-1) mod p (if period * a^r is invertible)

		ar := modPow(a, r, p)
		lhsCoeff := (r * ar) % p
		rhs := (b - lhsCoeff + p) % p

		periodAr := (period * ar) % p

		if periodAr == 0 {
			// period * a^r ≡ 0 mod p
			// This means either period ≡ 0 mod p or a^r ≡ 0 mod p
			// Since a < p and p is prime, a^r ≡ 0 mod p only if a ≡ 0, but a >= 1
			// So period ≡ 0 mod p
			// Then we need rhs ≡ 0 mod p
			if rhs == 0 {
				// Any k works, so all n ≡ r mod period are solutions
				// Count n in [1, x] with n ≡ r mod period
				count += countResidue(r, period, x)
			}
			// Otherwise no solution
		} else {
			// period * a^r is invertible mod p
			// k ≡ rhs * inverse(period * a^r) mod p
			invPeriodAr := modInverse(periodAr, p)
			k0 := (rhs * invPeriodAr) % p

			// k = k0 + t * p for t >= 0
			// n = r + (k0 + t * p) * period = r + k0 * period + t * p * period
			// n ≡ r + k0 * period mod (p * period)
			baseN := r + k0*period
			modulus := p * period

			// Count n in [1, x] with n ≡ baseN mod modulus
			count += countResidue(baseN, modulus, x)
		}
	}

	fmt.Println(count)
}

// findPeriod finds the multiplicative order of a modulo p
func findPeriod(a, p int64) int64 {
	// The order divides p-1
	// We find the smallest k such that a^k ≡ 1 mod p
	// First, factorize p-1
	n := p - 1
	factors := factorize(n)

	// For each divisor d of p-1 (in increasing order), check if a^d ≡ 1 mod p
	// The smallest such d is the order
	order := n
	for _, f := range factors {
		// Try dividing out factor f
		tempOrder := order
		for tempOrder%f == 0 {
			tempOrder /= f
			if modPow(a, tempOrder, p) == 1 {
				order = tempOrder
			} else {
				tempOrder *= f
				break
			}
		}
	}

	return order
}

// factorize returns the prime factors of n
func factorize(n int64) []int64 {
	factors := []int64{}
	d := int64(2)
	for d*d <= n {
		if n%d == 0 {
			factors = append(factors, d)
			for n%d == 0 {
				n /= d
			}
		}
		d++
	}
	if n > 1 {
		factors = append(factors, n)
	}
	return factors
}

// modPow computes a^b mod m
func modPow(a, b, m int64) int64 {
	result := int64(1)
	a = a % m
	for b > 0 {
		if b&1 == 1 {
			result = (result * a) % m
		}
		b = b >> 1
		a = (a * a) % m
	}
	return result
}

// modInverse computes the modular inverse of a mod p using Fermat's little theorem
func modInverse(a, p int64) int64 {
	return modPow(a, p-2, p)
}

// countResidue counts numbers n in [1, x] such that n ≡ r mod m
func countResidue(r, m, x int64) int64 {
	if r == 0 {
		// n ≡ 0 mod m, so n = m, 2m, 3m, ...
		return x / m
	}
	// n ≡ r mod m, so n = r, r+m, r+2m, ...
	if r > x {
		return 0
	}
	return (x-r)/m + 1
}
